{
  "name": "http_request",
  "description": "Performs HTTP requests to external APIs",
  "inputs": [
    {
      "name": "url",
      "type": "string",
      "description": "Destination endpoint URL",
      "required": true
    },
    {
      "name": "method",
      "type": "string",
      "description": "HTTP method (e.g. GET, POST)",
      "required": false
    }
  ],
  "outputs": [
    {
      "name": "status_code",
      "type": "number",
      "description": "HTTP response status code"
    },
    {
      "name": "response_body",
      "type": "string",
      "description": "Raw response payload"
    }
  ]
}

{
  "name": "http_request_v2",
  "description": "Performs optimized HTTP requests to external APIs",
  "version": 1,
  "inputs": [
    {
      "name": "url",
      "type": "string",
      "description": "Destination endpoint URL",
      "required": true
    }
  ],
  "outputs": [
    {
      "name": "status_code",
      "type": "number",
      "description": "HTTP response status code"
    }
  ]
}

{
  "name": "search_and_summarize",
  "content": "Search the web using {{tool:{{toolId}}}} and synthesize the findings."
}

